    await callerFor(USER).deleteEverything();
    expect(nightDeletes).toEqual([USER]);
    expect((await callerFor(OTHER).me()).profile).toBe("bestValue");
  });

  test("if the night stores fail, the user stays so the delete can be retried", async () => {
    const { callerFor, failNightsWith, users } = setup();
