/** Failures other features can catch. Messages never include consent choices or health values. */
export class AccountStorageError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "AccountStorageError";
  }
}

/** The user asked to delete everything and it has not finished: nothing new may be stored. */
export class AccountDeletingError extends Error {
  constructor() {
    super("Account is being deleted");
    this.name = "AccountDeletingError";
  }
}

import { type ConsentChoices, NO_CONSENT } from "@kip/shared/account";
import type { TravellerProfile } from "@kip/shared/domain";
import type { Collection, Db } from "mongodb";
import { mongo } from "../../db/mongo";
import { AccountStorageError } from "./errors";

/** One per user in Mongo `users`: consent choices and the Quiet Stays profile, nothing else. */
export type UserDocument = {
  userId: string;
  consent: ConsentChoices;
  consentUpdatedAt: string | null;
  profile: TravellerProfile | null;
  /** Set when "delete everything" starts; the document goes when it finishes */
  deletingSince: string | null;
  createdAt: string;
  updatedAt: string;
};

export type AccountRepo = {
  get(userId: string): Promise<UserDocument | null>;
  /** Creates the user on first write. `at` is an ISO timestamp */
  saveConsent(userId: string, consent: ConsentChoices, at: string): Promise<UserDocument>;
  saveProfile(userId: string, profile: TravellerProfile, at: string): Promise<UserDocument>;
  markDeleting(userId: string, at: string): Promise<void>;
  /** Number of user documents removed: 1, or 0 if there was none */
  remove(userId: string): Promise<number>;
};

export type StoredUser = Omit<UserDocument, "userId"> & { _id: string };

type UserFields = Partial<Omit<StoredUser, "_id" | "createdAt" | "updatedAt">>;

function documentOf({ _id, ...rest }: StoredUser): UserDocument {
  return { userId: _id, ...rest, deletingSince: rest.deletingSince ?? null };
}

async function guard<T>(action: "read" | "write", run: () => Promise<T>): Promise<T> {
  try {
    return await run();
  } catch (error) {
    if (error instanceof AccountStorageError) throw error;
    // The driver's message can echo the update. Report the action only.
    throw new AccountStorageError(`Could not ${action === "read" ? "read" : "store"} the account`);
  }
}

/**
 * Mongo `users`, keyed by user ID. Connecting waits until the first call, so imports stay
 * side-effect free. Tests pass their own `db`.
 */
export function createAccountRepo(db: () => Db = mongo): AccountRepo {
  const users = (): Collection<StoredUser> => db().collection<StoredUser>("users");

  /** `set` and `onInsert` must not share a field: Mongo rejects the update if they do. */
  async function upsert(
    userId: string,
    set: UserFields,
    onInsert: UserFields,
    at: string,
  ): Promise<UserDocument> {
    const stored = await users().findOneAndUpdate(
      { _id: userId },
      { $set: { ...set, updatedAt: at }, $setOnInsert: { ...onInsert, createdAt: at } },
      { upsert: true, returnDocument: "after" },
    );
    if (!stored) throw new AccountStorageError("Could not store the account");
    return documentOf(stored);
  }

  return {
    get: (userId) =>
      guard("read", async () => {
        const stored = await users().findOne({ _id: userId });
        return stored ? documentOf(stored) : null;
      }),
    saveConsent: (userId, consent, at) =>
      guard("write", () =>
        upsert(
          userId,
          { consent, consentUpdatedAt: at },
          { profile: null, deletingSince: null },
          at,
        ),
      ),
    saveProfile: (userId, profile, at) =>
      guard("write", () =>
        upsert(
          userId,
          { profile },
          { consent: { ...NO_CONSENT }, consentUpdatedAt: null, deletingSince: null },
          at,
        ),
      ),
    markDeleting: (userId, at) =>
      guard("write", async () => {
        await upsert(
          userId,
          { deletingSince: at },
          { consent: { ...NO_CONSENT }, consentUpdatedAt: null, profile: null },
          at,
        );
      }),
    remove: (userId) =>
      guard("write", async () => (await users().deleteOne({ _id: userId })).deletedCount),
  };
}

import {
  type AccountView,
  accountView,
  type ConsentChoices,
  consentChoices,
  type DeleteEverythingResult,
  deleteEverythingResult,
  NO_CONSENT,
  travellerProfile,
} from "@kip/shared/account";
import type { TravellerProfile } from "@kip/shared/domain";
import { deleteUserNights, type NightDeleteCounts } from "../night";
import { AccountDeletingError } from "./errors";
import { type AccountRepo, createAccountRepo, type UserDocument } from "./repo";

// Business logic for `account`. Other features may call only what index.ts re-exports from here,
// so inputs are validated here as well as in the router.
// Nothing here logs: consent choices sit next to special-category health data (docs/DOMAIN.md).

export type AccountService = {
  me(userId: string): Promise<AccountView>;
  setConsent(userId: string, consent: ConsentChoices): Promise<AccountView>;
  setProfile(userId: string, profile: TravellerProfile): Promise<AccountView>;
  /**
   * What an upload may store for this user. Once the user has answered, each data type needs
   * both their stored consent and the upload's own flag. Before that, the upload's flags stand.
   * Throws AccountDeletingError while "delete everything" is running.
   */
  allowedConsent(userId: string, requested: ConsentChoices): Promise<ConsentChoices>;
  /**
   * Marks the user as deleting, removes their nights (Mongo and every Tiger series, through the
   * night service), then the user. Solana memos hold only a hash of a night log and cannot be
   * removed from the chain.
   */
  deleteEverything(userId: string): Promise<DeleteEverythingResult>;
};

export type AccountDeps = {
  repo: AccountRepo;
  deleteUserNights: (userId: string) => Promise<NightDeleteCounts>;
  now?: () => Date;
};

function toView(userId: string, user: UserDocument | null): AccountView {
  return accountView.parse({
    userId,
    consent: user ? user.consent : NO_CONSENT,
    consentUpdatedAt: user ? user.consentUpdatedAt : null,
    profile: user ? user.profile : null,
  });
}

function addCounts(a: NightDeleteCounts, b: NightDeleteCounts): NightDeleteCounts {
  return {
    nights: a.nights + b.nights,
    noiseRows: a.noiseRows + b.noiseRows,
    vitalRows: a.vitalRows + b.vitalRows,
    stageRows: a.stageRows + b.stageRows,
  };
}

export function createAccountService(deps: AccountDeps): AccountService {
  const now = deps.now ?? (() => new Date());

  return {
    async me(userId) {
      return toView(userId, await deps.repo.get(userId));
    },

    async setConsent(userId, consent) {
      const choices = consentChoices.parse(consent);
      return toView(userId, await deps.repo.saveConsent(userId, choices, now().toISOString()));
    },

    async setProfile(userId, profile) {
      const chosen = travellerProfile.parse(profile);
      return toView(userId, await deps.repo.saveProfile(userId, chosen, now().toISOString()));
    },

    async allowedConsent(userId, requested) {
      const asked = consentChoices.parse(requested);
      const user = await deps.repo.get(userId);
      if (user?.deletingSince) throw new AccountDeletingError();
      if (!user || user.consentUpdatedAt === null) return asked;
      return {
        microphone: asked.microphone && user.consent.microphone,
        health: asked.health && user.consent.health,
        location: asked.location && user.consent.location,
      };
    },

    async deleteEverything(userId) {
      // The mark stops new uploads (through allowedConsent) and stays if a store fails, so the
      // delete can be retried. The second pass catches a night that was mid-upload when the
      // first pass ran.
      await deps.repo.markDeleting(userId, now().toISOString());
      const first = await deps.deleteUserNights(userId);
      const second = await deps.deleteUserNights(userId);
      const users = await deps.repo.remove(userId);
      return deleteEverythingResult.parse({ users, ...addCounts(first, second) });
    },
  };
}

export const liveAccount = createAccountService({
  repo: createAccountRepo(),
  // Read at call time, so night can import account without a load-order cycle.
  deleteUserNights: (userId) => deleteUserNights(userId),
});

export const getAccount = liveAccount.me;
export const allowedConsent = liveAccount.allowedConsent;

